// Lightweight login JS matching Views/Account/Login.cshtml
(function ($) {
    'use strict';

    $(function () {
        var $form = $('#loginForm');
        var $username = $('#username');
        var $password = $('#password');
        var $submit = $form.find('button[type="submit"]');

        function clearErrors() {
            $form.find('.text-danger').text('');
            $form.find('.is-invalid').removeClass('is-invalid');
        }

        function showFieldError($field, msg) {
            $field.addClass('is-invalid');
            // find nearest validation span generated by asp-validation-for
            var $span = $field.closest('.form-floating').find('[asp-validation-for], .text-danger');
            if ($span.length === 0) {
                $span = $field.closest('.form-floating').find('.text-danger');
            }
            $span.text(msg);
        }

        $form.on('submit', function (e) {
            clearErrors();
            var valid = true;
            if (!$username.val() || $username.val().trim() === '') {
                showFieldError($username, 'Vui lòng nhập tên đăng nhập');
                valid = false;
            }
            if (!$password.val() || $password.val().trim() === '') {
                showFieldError($password, 'Vui lòng nhập mật khẩu');
                valid = false;
            }
            if (!valid) {
                e.preventDefault();
                $form.addClass('shake');
                setTimeout(function () { $form.removeClass('shake'); }, 400);
                return false;
            }

            // show simple loading state
            $submit.prop('disabled', true).text('Đang xử lý...');
        });

        // remove errors on input
        $username.add($password).on('input', function () {
            $(this).removeClass('is-invalid');
            $(this).closest('.form-floating').find('.text-danger').text('');
        });

        // focus username on load
        $username.trigger('focus');

        // keyboard shortcuts
        $(document).on('keydown', function (e) {
            // Alt+L focus username
            if (e.altKey && (e.key === 'l' || e.key === 'L')) {
                e.preventDefault();
                $username.focus();
            }
            // Ctrl+Enter submit
            if (e.ctrlKey && e.key === 'Enter') {
                e.preventDefault();
                $form.trigger('submit');
            }
        });
    });

})(jQuery);
